{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "description": "Early Bird Ticket: 2026 Annual Tech Conference", // enter the link description shown to the customer
  "amount": {{paylink_amount}}, // enter your amount here in paisa (min 1)
  "paymentFlow": {
    "type": "PAYLINK",
    "customerDetails": {
      "name": "{{customer_name}}", // enter the customer name here
      "phoneNumber": "{{customer_phone}}", // mandatory - enter customer phone (+9197xxxxxx89 or 97xxxxxx89, no spaces/hyphens)
      "email": "{{customer_email}}" // enter the customer email here
    },
    "notificationChannels": {
      "SMS": false, // set true to have PhonePe deliver the link over SMS
      "EMAIL": false // set true to have PhonePe deliver the link over email
    },
    "expireAt": {{paylink_expire_at}} // enter link expiry here in epoch ms (auto-defaulted to now+7d; max 45d)
  },
  "metaInfo": {
    "udf1": "udf1", // optional passthrough fields udf1-udf5
    "udf2": "udf2"
  }
}

{
  "merchantOrderId": "{{merchant_order_id}}", // enter the order id of the link to re-notify
  "notificationChannels": {
    "sms": true, // set true to re-send over SMS
    "email": false // set true to re-send over email
  }
}

{
  "merchantRefundId": "{{merchant_refund_id}}", // auto-generated each run by pre-request script (REFUND_<timestamp>)
  "originalMerchantOrderId": "{{merchant_order_id}}", // enter the original order id to refund here
  "amount": {{refund_amount}} // enter refund amount here in paisa (min 100, must be <= captured amount)
}
